def main():
    target = Path(__file__).resolve().parents[1] / "deep_research_prompt.md"
    with target.open("x", encoding="utf-8", newline="\n") as output:
        output.write(PROMPT)
    if target.read_text(encoding="utf-8") != PROMPT:
        raise RuntimeError("Saved prompt differs from prepared content")
    questions = [line for line in PROMPT.splitlines() if line.startswith("### ")]
    if len(questions) != 7:
        raise RuntimeError("The prompt must contain seven research questions")
    print("Created and verified: deep_research_prompt.md (7 research questions)")


if __name__ == "__main__":
    main()
